const COURSE = [
{unit:"Unit I",title:"Internet Technologies",description:"Understand how browsers, servers and network protocols work together.",lessons:[
{heading:"Internet and client-server model",explain:"The Internet is a worldwide network of connected devices. A client requests a resource and a server responds.",points:["Client: browser or application that sends a request.","Server: computer or software that processes requests.","Protocol: agreed rules for communication."]},
{heading:"TCP/IP, HTTP, DNS and SMTP",explain:"These protocols support different parts of communication over the Internet.",points:["TCP/IP: protocol suite used to move data between networks.","HTTP: transfers web pages and other web resources.","DNS: maps domain names to IP addresses.","SMTP: sends email between mail servers."]},
{heading:"IP addressing and domain names",explain:"An IP address identifies a device or network interface. DNS helps translate a human-friendly domain name into an IP address.",code:"Browser requests: portal.example\\n        |\\n        v\\nDNS lookup -> 203.0.113.20\\n        |\\n        v\\nHTTP request reaches web server",result:"The browser can contact the server using the resolved IP address."},
{heading:"HTML basics",explain:"HTML (HyperText Markup Language) defines the structure of a web page using elements.",code:"<!doctype html>\\n<html>\\n<head><title>My Page</title></head>\\n<body>\\n  <h1>Welcome</h1>\\n  <p>Learning web technology.</p>\\n</body>\\n</html>",result:"A page with a heading and paragraph."},
{heading:"JavaScript fundamentals",explain:"JavaScript runs in the browser to react to events, validate forms and update content.",code:"const btn = document.querySelector('#show');\\nbtn.addEventListener('click', () => {\\n  document.querySelector('#msg').textContent = 'Hi there!';\\n});",result:"Clicking the button changes the message."},
{heading:"Front-end vs server-side scripting",explain:"Front-end scripts run in the browser. Server-side scripts run on the server and can process requests or access databases.",points:["Front end: HTML, CSS and JavaScript.","Server side: PHP is executed by the web server.","Validate important data on the server, not only in the browser."]}
]},
{unit:"Unit II",title:"Introduction to PHP & String Handling",description:"Practise PHP syntax, variables, decisions, loops, operators and string functions.",lessons:[
{heading:"PHP syntax and echo",explain:"PHP code is written between <?php and ?> tags. Statements normally end with a semicolon.",code:"<?php\\necho 'Hello from PHP';\\n?>",result:"Hello from PHP"},
{heading:"Variables and constants",explain:"Variables begin with $. Constants hold named values that should not be reassigned.",code:"<?php\\n$student = 'Meera';\\n$year = 2;\\ndefine('COURSE', 'BCA');\\necho $student . ' ' . COURSE;\\n?>",result:"Meera BCA"},
{heading:"Data types, operators and expressions",explain:"PHP includes integer, float, string, boolean, array, object and NULL types. Operators perform arithmetic, comparison and logical operations.",code:"<?php\\n$a = 17; $b = 5;\\necho $a % $b;\\necho $a > $b;\\n?>",result:"2 and 1 (true)."},
{heading:"Decision making",explain:"if, elseif, else and switch let a program choose an action based on a condition.",code:"<?php\\n$score = 64;\\nif ($score >= 40) echo 'Pass';\\nelse echo 'Try again';\\n?>",result:"Pass"},
{heading:"Looping constructs",explain:"for, while, do-while and foreach repeat instructions. foreach is useful for arrays.",code:"<?php\\n$colors = ['red', 'blue', 'green'];\\nforeach ($colors as $c) {\\n  echo $c . ' ';\\n}\\n?>",result:"red blue green"},
{heading:"Mixing PHP with HTML",explain:"PHP can generate dynamic HTML. Escape values from users before displaying them in a page.",code:"<?php $user = 'Karan'; ?>\\n<h2>Hello, <?= htmlspecialchars($user) ?></h2>",result:"Hello, Karan"},
{heading:"String creation and access",explain:"A string stores text. Individual characters can be accessed using zero-based indexes.",code:"<?php\\n$word = 'BACKEND';\\necho $word[0];\\necho $word[4];\\n?>",result:"BE"},
{heading:"Search, replace and format strings",explain:"PHP string functions can find text, replace part of a string, and change letter case.",code:"<?php\\n$s = 'Study PHP daily';\\necho strpos($s, 'PHP');\\necho str_replace('daily', 'well', $s);\\necho strtoupper('php');\\n?>",result:"6 · Study PHP well · PHP"}
]},
{unit:"Unit III",title:"Handling HTML Forms with PHP",description:"Create forms, submit values with GET or POST, and validate information on the server.",lessons:[
{heading:"Create an HTML form",explain:"The action attribute names the server file that receives form data. The method controls how the browser sends it.",code:"<form action='receive.php' method='post'>\\n  <label>Name <input name='student' required></label>\\n  <button type='submit'>Submit</button>\\n</form>",result:"The student field is sent to receive.php."},
{heading:"GET method",explain:"GET sends values in the URL query string. It is useful for searches and non-sensitive retrieval requests.",code:"<?php\\n$keyword = trim($_GET['q'] ?? '');\\necho htmlspecialchars($keyword);\\n?>",result:"A URL such as find.php?q=php displays php."},
{heading:"POST method",explain:"POST sends values in the request body. It is commonly used to submit forms. HTTPS is still needed to protect data in transit.",code:"<?php\\nif ($_SERVER['REQUEST_METHOD'] === 'POST') {\\n  $city = trim($_POST['city'] ?? '');\\n  echo htmlspecialchars($city);\\n}\\n?>",result:"Displays the submitted city after HTML escaping."},
{heading:"GET vs POST",explain:"Both send data to the server but suit different tasks.",points:["GET: data appears in the URL; commonly used to retrieve or search.","POST: data is sent in the request body; commonly used to submit or change data.","Neither method encrypts data; use HTTPS for transport security."]},
{heading:"Student registration validation",explain:"Server-side validation checks submitted data even if the HTML form uses required. A real app should also include CSRF protection and database constraints.",code:"<?php\\n$errors = [];\\n$name = trim($_POST['name'] ?? '');\\n$email = trim($_POST['email'] ?? '');\\nif ($name === '') $errors[] = 'Name required';\\nif (!filter_var($email, FILTER_VALIDATE_EMAIL))\\n  $errors[] = 'Invalid email';\\nif (!$errors) echo 'Details accepted';\\nforeach ($errors as $e) echo htmlspecialchars($e) . '<br>';\\n?>",result:"Shows validation errors or Details accepted."},
{heading:"Login and password verification",explain:"Store password hashes rather than plain-text passwords. password_verify() checks a submitted password against a saved hash.",code:"<?php\\n// $hash is retrieved from the users table.\\n$password = $_POST['password'] ?? '';\\nif (password_verify($password, $hash)) {\\n  echo 'Login successful';\\n} else {\\n  echo 'Invalid login';\\n}\\n?>",result:"Login successful only if the password matches the stored hash."}
]},
{unit:"Unit IV",title:"Database Connectivity with MySQL",description:"Create databases and tables, connect from PHP, insert and retrieve records, and manipulate data.",lessons:[
{heading:"Database and MySQL concepts",explain:"A relational database organises information into tables. MySQL is a relational database management system.",points:["Database: collection of related information.","Table: data arranged in rows and columns.","Primary key: uniquely identifies a row.","SQL: language used to define and manipulate data."]},
{heading:"Create database and table",explain:"CREATE DATABASE makes a database. CREATE TABLE defines its columns and constraints.",code:"CREATE DATABASE training;\\nUSE training;\\nCREATE TABLE students (\\n id INT AUTO_INCREMENT PRIMARY KEY,\\n name VARCHAR(80) NOT NULL,\\n course VARCHAR(30)\\n);",result:"Creates training database and students table."},
{heading:"Connect PHP to MySQL using PDO",explain:"PDO provides a consistent interface for database access. Keep real credentials private and handle connection errors safely.",code:"<?php\\n$pdo = new PDO(\\n 'mysql:host=localhost;dbname=training;charset=utf8mb4',\\n 'db_user', 'db_password',\\n [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]\\n);\\necho 'Connected';\\n?>",result:"Connected, if the database and credentials are correct."},
{heading:"Insert records",explain:"Prepared statements keep SQL separate from user values and help prevent SQL injection.",code:"<?php\\n$stmt = $pdo->prepare(\\n 'INSERT INTO students (name, course) VALUES (?, ?)'\\n);\\n$stmt->execute(['Ishita', 'BCA']);\\n?>",result:"Adds Ishita's BCA record to the table."},
{heading:"Retrieve records",explain:"SELECT reads records from a table. Escape data before displaying it in HTML.",code:"<?php\\n$stmt = $pdo->query('SELECT name, course FROM students');\\nforeach ($stmt as $row) {\\n echo htmlspecialchars($row['name']) . '<br>';\\n}\\n?>",result:"Displays the student names returned by MySQL."},
{heading:"Update and delete data",explain:"UPDATE changes existing records and DELETE removes records. Use a WHERE clause to target the intended rows.",code:"<?php\\n$u = $pdo->prepare('UPDATE students SET course=? WHERE id=?');\\n$u->execute(['MCA', 1]);\\n$d = $pdo->prepare('DELETE FROM students WHERE id=?');\\n$d->execute([4]);\\n?>",result:"Updates record 1 and deletes record 4."}
]}
];